// Validación en vivo del checkout
function fieldErr(inp,msg){
  var err=inp.parentElement.querySelector('.sb-shop__ferr');
  if(!msg){if(err)err.remove();inp.classList.remove('sb-shop__input--bad');return;}
  if(!err){err=document.createElement('span');err.className='sb-shop__ferr';inp.parentElement.appendChild(err);}
  err.textContent=msg;inp.classList.add('sb-shop__input--bad');
}
var nameI=form&&form.querySelector('[name=name]');
var emailI=form&&form.querySelector('[name=email]');
function checkName(){var ok=nameI.value.trim().length>=2;fieldErr(nameI,ok?'':'Escribe tu nombre');return ok;}
function checkEmail(){var ok=/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(emailI.value.trim());fieldErr(emailI,ok?'':'Email no v\\u00E1lido');return ok;}
if(nameI){nameI.addEventListener('blur',checkName);nameI.addEventListener('input',function(){fieldErr(nameI,'');});}
if(emailI){emailI.addEventListener('blur',checkEmail);emailI.addEventListener('input',function(){fieldErr(emailI,'');});}

function showMsg(t2,isErr){if(!msgEl)return;msgEl.textContent=t2;msgEl.hidden=false;msgEl.className=isErr?'sb-shop__msg sb-shop__msg--error':'sb-shop__msg';}
function showSuccess(list,total,code){
  if(!panel)return;
  if(form)form.hidden=true;
  var box=document.createElement('div');box.className='sb-shop__success';
  var h=document.createElement('p');h.className='sb-shop__success-title';h.textContent='\\u2705 '+OK_MSG;box.appendChild(h);
  list.forEach(function(l){
    var row=document.createElement('div');row.className='sb-shop__success-line';
    var a=document.createElement('span');a.textContent=l.qty+' \\u00D7 '+l.name;
    var b2=document.createElement('span');b2.textContent=money(l.qty*l.price);
    row.appendChild(a);row.appendChild(b2);box.appendChild(row);
  });
  var tr=document.createElement('div');tr.className='sb-shop__success-line sb-shop__success-total';
  var ta=document.createElement('span');ta.textContent='Total (IVA incluido)';
  var tb=document.createElement('span');tb.textContent=money(total);
  tr.appendChild(ta);tr.appendChild(tb);box.appendChild(tr);
  if(code){var rf=document.createElement('p');rf.className='sb-shop__success-ref';rf.textContent='Referencia del pedido: '+code;box.appendChild(rf);}
  panel.appendChild(box);
}

if(form)form.addEventListener('submit',function(e){
  e.preventDefault();
  if(msgEl){msgEl.hidden=true;}
  var okName=checkName(),okEmail=checkEmail();
  if(!okName||!okEmail)return;
  var list=items();
  if(list.length===0){showMsg('Tu carrito est\\u00E1 vac\\u00EDo.',true);return;}
  if(!ENDPOINT){showMsg('La tienda no est\\u00E1 activa todav\\u00EDa.',true);return;}
  var total=0;list.forEach(function(l){total+=l.qty*l.price;});
  var fd=new FormData(form);
  var body={
    customer:{name:String(fd.get('name')||''),email:String(fd.get('email')||''),phone:String(fd.get('phone')||''),address:String(fd.get('address')||''),notes:String(fd.get('notes')||'')},
    lines:list.map(function(l){return {itemId:l.id,quantity:l.qty};}),
    website:String(fd.get('website')||'')
  };
  var submitBtn=form.querySelector('button[type=submit]');
  if(submitBtn)submitBtn.disabled=true;
  fetch(ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
    .then(function(r){return r.json().catch(function(){return {};}).then(function(d){return {ok:r.ok&&d.ok,data:d};});})
    .then(function(res){
      if(res.ok){
        save({});refresh();
        showSuccess(list,total,res.data.orderCode||'');
      }else{
        showMsg(res.data&&res.data.error?res.data.error:'No se pudo enviar el pedido. Int\\u00E9ntalo de nuevo.',true);
      }
    })
    .catch(function(){showMsg('No se pudo enviar el pedido. Int\\u00E9ntalo de nuevo.',true);})
    .then(function(){if(submitBtn)submitBtn.disabled=false;});
});

